def run(ctx):
    TOP_K = 10
    CANDIDATE_K = 20

    query = ctx.query or "0-dimensional biomaterials show inductive properties"
    analysis = ctx.query_understanding.analyze(query)

    entity_texts = []
    for entity in analysis.get("entities", []):
        text = entity.get("text", "")
        if text:
            entity_texts.append(text)

    linked_entities = []
    if entity_texts:
        linked_entities = ctx.entity_linking.link(" ".join(entity_texts))

    rewrite_result = ctx.query_rewrite.rewrite(
        query,
        analysis=analysis,
        linked_entities=linked_entities,
    )
    rewrites = rewrite_result.get("rewrites", [])

    tokens = query.replace("-", " ").replace("/", " ").split()
    lower_query = query.lower()
    intents = analysis.get("intents", [])
    subqueries = analysis.get("subqueries", [])
    noun_chunks = analysis.get("noun_chunks", [])

    exact_signal = False
    semantic_signal = False
    if "0-dimensional" in lower_query or "zero-dimensional" in lower_query:
        exact_signal = True
    if len(entity_texts) >= 2 or len(tokens) > 6 or subqueries or noun_chunks:
        semantic_signal = True
    if "inductive" in lower_query or "properties" in lower_query or "show" in lower_query:
        semantic_signal = True
    if intents:
        semantic_signal = True

    mode = "bm25"
    bm25_weight = 0.65
    if exact_signal and semantic_signal:
        mode = "hybrid"
        bm25_weight = 0.7
    elif semantic_signal:
        mode = "dense"
        bm25_weight = 0.45

    search_queries = [query]
    for rewritten in rewrites:
        if rewritten and rewritten not in search_queries:
            search_queries.append(rewritten)
    for subquery in subqueries:
        if subquery and subquery not in search_queries:
            search_queries.append(subquery)

    must_terms = []
    if "biomaterials" in lower_query:
        must_terms.append("biomaterials")

    should_terms = []
    for term in ["0-dimensional", "zero-dimensional", "inductive", "properties"]:
        if term in lower_query or term not in should_terms:
            should_terms.append(term)

    ctx.log("agentic_plan", {
        "query": query,
        "mode": mode,
        "bm25_weight": bm25_weight,
        "rewrite_method": rewrite_result.get("method", ""),
        "rewrite_count": len(rewrites),
        "entity_count": len(entity_texts),
        "candidate_limit": CANDIDATE_K,
    })

    by_doc_id = {}
    for search_query in search_queries:
        if mode == "hybrid":
            hits = ctx.search.search(
                search_query,
                mode="hybrid",
                top_k=CANDIDATE_K,
                bm25_weight=bm25_weight,
                must_terms=must_terms,
                should_terms=should_terms,
            )
        elif mode == "dense":
            hits = ctx.search.search(
                search_query,
                mode="dense",
                top_k=CANDIDATE_K,
                should_terms=should_terms,
            )
        else:
            hits = ctx.search.search(
                search_query,
                mode="bm25",
                top_k=CANDIDATE_K,
                must_terms=must_terms,
                should_terms=should_terms,
            )

        for hit in hits:
            doc_id = hit.get("doc_id", "")
            if not doc_id:
                continue
            current = by_doc_id.get(doc_id)
            if current is None or hit.get("score", 0) > current.get("score", 0):
                by_doc_id[doc_id] = hit

    candidates = list(by_doc_id.values())
    candidates.sort(key=lambda item: item.get("score", 0), reverse=True)
    candidates = candidates[:CANDIDATE_K]

    ranked_hits = ctx.ranking.rerank(query, candidates, top_k=TOP_K)
    ctx.candidate_pool = len(candidates)

    ctx.log("reflection", {
        "selected_mode": mode,
        "searched_queries": len(search_queries),
        "deduped_candidates": len(candidates),
        "returned_hits": len(ranked_hits),
        "reason": "Hybrid/dense routing is used for semantic biomaterial-property matching while BM25 weight preserves exact zero-dimensional terminology.",
    })

    return {"hits": ranked_hits, "candidates": candidates}
